def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if len(alive_opponents) == 0:
        solo_bid = DAILY_SALARY * 0.2
        if hp <= 2 or no_water_days >= 2:
            solo_bid = DAILY_SALARY * 0.45
        return float(max(0.0, min(budget, solo_bid)))

    prev_bids = []
    aggressive_count = 0
    desperate_count = 0
    rich_aggressive = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                aggressive_count += 1
            if bid >= 160:
                rich_aggressive += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_pressure = 1.0
    if supply >= 23:
        supply_pressure = 0.72
    elif supply >= 20:
        supply_pressure = 0.84
    elif supply >= 18:
        supply_pressure = 0.96
    else:
        supply_pressure = 1.12

    health_pressure = 0.0
    if hp <= 2 or no_water_days >= 2:
        health_pressure = 55.0
    elif hp <= 4 or no_water_days >= 1:
        health_pressure = 22.0

    bid = 0.0

    if highest_prev >= 160:
        if hp >= 6 and no_water_days == 0 and supply >= 20:
            bid = 58.0
        else:
            bid = 96.0 + health_pressure * 0.35
    elif highest_prev >= 120:
        bid = 74.0 + health_pressure * 0.45
    elif highest_prev >= 80:
        bid = 62.0 + health_pressure * 0.4
    elif highest_prev > 0:
        bid = max(48.0, avg_prev * 0.72) + health_pressure * 0.3
    else:
        bid = 52.0 + health_pressure * 0.3

    if desperate_count >= 2:
        bid += 12.0
    elif desperate_count == 1:
        bid += 6.0

    if aggressive_count >= 2 and hp >= 6 and no_water_days == 0 and supply >= 20:
        bid -= 8.0

    if rich_aggressive >= 1 and hp >= 7 and no_water_days == 0 and supply >= 22:
        bid -= 6.0

    bid *= supply_pressure

    if day >= 8 and hp <= 4:
        bid += 18.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 105.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 72.0)

    max_safe = budget
    if hp >= 7 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 1.15)
    elif hp >= 5:
        max_safe = min(max_safe, DAILY_SALARY * 1.55)
    else:
        max_safe = min(max_safe, DAILY_SALARY * 2.4)

    bid = max(0.0, min(bid, max_safe))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids and infer pressure.
    yesterday_bids = []
    near_max_flags = 0
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            yesterday_bids.append(b)
            # If they were close to their max bid, they likely keep bidding high.
            try:
                max_bid = float(prev.get('max_bid', o.get('max_bid', None))) if 'max_bid' in prev else None
            except Exception:
                max_bid = None
            if max_bid is not None and max_bid > 0:
                if b >= 0.85 * max_bid:
                    near_max_flags += 1

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Supply pressure: with higher supply, clearing cost should drop.
    # Normalize supply between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid target: slightly above typical survival bids, but not matching extreme outliers.
    # Use avg as anchor; if someone was extremely aggressive, add a small increment.
    base = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.55)

    # Escalation if highest bid is very high.
    if highest_prev_bid >= DAILY_SALARY * 1.3:
        base = max(base, DAILY_SALARY * 0.75)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        base = max(base, DAILY_SALARY * 0.62)

    # If supply is high, reduce bid slightly; if supply is low, increase.
    # supply_norm=1 => high supply => cheaper
    base = base * (1.0 - 0.18 * supply_norm) + base * (0.12 * (1.0 - supply_norm))

    # HP urgency: if I'm low HP or have water-stress, bid more.
    if hp <= 2:
        base *= 1.35
    elif hp <= 4:
        base *= 1.18

    if no_water_days >= 2:
        base *= 1.15

    # If multiple opponents were near-max yesterday, slightly raise to avoid being outbid.
    if near_max_flags >= 2:
        base *= 1.12

    # Hard cap: never exceed what we can afford; keep some budget for later.
    # Also avoid overbidding beyond a fraction of daily salary.
    affordability_cap = budget
    strategic_cap = DAILY_SALARY * 1.05
    final_bid = min(affordability_cap, strategic_cap, base)

    # Ensure non-negative.
    if final_bid < 0:
        final_bid = 0.0

    # If my budget is tiny, bid what I can.
    if budget <= 5:
        return min(budget, 5.0)

    # Add small day-based jitter to avoid ties/predictability.
    jitter = (day % 3) * 1.0
    final_bid = final_bid + jitter

    # Final clamp.
    final_bid = min(final_bid, affordability_cap)
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # 1. No active opponents: Bid minimal to conserve budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    # 2. Critical HP or missed water yesterday: Bid aggressively to survive.
    if my_status['no_water_days'] >= 1 or my_status['hp'] <= 2:
        # If it's the last day, bid everything if necessary
        if day_context['day'] == EPISODE_DAYS:
            return my_status['budget']
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 3. Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Calculate number of water slots available
    supply = day_context['supply']
    num_slots = int(supply // WATER_REQ)

    # 4. Abundant supply: If there are enough slots for everyone (me + alive opponents)
    # and my HP is good, bid low to save budget.
    if num_slots >= (num_alive_opponents + 1) and my_status['hp'] > 3:
        # Try to bid slightly above a minimal value or lowest previous bid to ensure winning a slot.
        if yesterday_bids:
            # Bid slightly above the minimum of previous bids, but not too low
            min_prev_bid = min(yesterday_bids)
            return min(my_status['budget'], max(DAILY_SALARY * 0.25, min_prev_bid * 1.05))
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.3) # Default low bid

    # 5. Scarce/Moderate supply or not abundant, and not critical HP.
    # React to opponent's previous bids.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If highest previous bid was very high (e.g., > 80% of daily salary)
        # and my HP is not critical, consider if I can afford to lose or need to win.
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 5: # Good HP, can afford to lose a round or bid lower
                return min(my_status['budget'], DAILY_SALARY * 0.4)
            else: # Moderate HP, need water, bid aggressively but not max
                return min(my_status['budget'], DAILY_SALARY * 0.9)
        else: # Highest previous bid was moderate
            # Bid slightly above the highest previous bid to secure a slot
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # 6. Default bid if no previous bids (e.g., Day 1) and not critical HP
    # or if the above conditions don't apply.
    # Adjust based on perceived competition.
    if num_slots <= (num_alive_opponents + 1): # Competitive situation
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else: # Less competitive (more slots than current competitors, but not "abundant" by earlier check)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    alive_opponents = [opp for opp in opponents_status.values() if opp['alive']]
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    highest_prev = max(prev_bids) if prev_bids else 0
    # Base bid: if supply is scarce, bid higher
    if supply < 18:
        base = DAILY_SALARY * 0.85  # ~119
    else:
        base = DAILY_SALARY * 0.75  # ~105
    # Adjust based on yesterday's high
    if highest_prev > 0:
        target = max(base, highest_prev + 10)
    else:
        target = base
    # Urgency from hp
    if my_status['hp'] <= 2:
        target = min(DAILY_SALARY * 0.95, target + 20)
    elif my_status['hp'] <= 5:
        target = min(DAILY_SALARY * 0.9, target + 10)
    # Never exceed budget
    return min(my_status['budget'], target)
